import {forcedLaborPeople} from './economy-labor.js?v=43.1';
import {economicNodes} from './economy-rural.js?v=43.1';
import {populationDescription} from './economy-society.js?v=43.1';
import {tradePolicyHTML,bindTradePolicies} from './economy-policy-ui.js?v=43.1';
import {tradeQuote,quotedUnitCost} from './economy-policy.js?v=43.1';
import {createMarketComparisons} from './economy-price-comparison.js?v=43.1';
import {buildEconomicMap,ECONOMIC_MODES,goodSymbol} from './economy-map-core.js?v=43.1';
import {createEconomy,money} from './economy-core.js?v=43.1';
import {simulateEconomy} from './economy-simulation.js?v=43.1';
import {createMarkets,routeFlows,pairKey,applyEconomicDiplomacy,atWar,tradeGraph} from './economy-trade.js?v=43.1';
import {createEconomyUI as createWorkbench} from './economy-ui.js?v=43.1';
import {incomeReport,aggregateIncome} from './economy-income.js?v=43.1';
import {tradeRelation} from './economy-policy.js?v=43.1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Number(n||0).toLocaleString('pt-BR',{maximumFractionDigits:2});
export const goodIcon=g=>g.i===77?'✦':[72,73].includes(g.i)?'🦴':[74,75].includes(g.i)?'🌋':[4,5,6,7,8,23,34,76].includes(g.i)?'⛏':g.tags?.includes('military')?'⚔':g.tags?.includes('food')?'🌾':g.i===1?'🌲':g.i===53?'⛵':g.kind==='manufacture'?'⚒':'◈';
export async function createEconomyLedger(options){
 const {D,provinces,provinceAt,title,toast,beforeOpen,onChange=()=>{},onMap=()=>{},onRoute=()=>{},focus=()=>{}}=options;
 let goodsBasis='specialization';
 let panel=null,section='world',view={kind:'world'},good=4,marketId=null,cache=null,busy=false,query='',order='value',basis='current',diploA=12,diploB=13,diploRelation='Neutral';
 const baselineDiplomacy=new Map(D.states.map(s=>[s.i,structuredClone(s.diplomacy||[])]));function syncDiplomacy(){for(const s of D.states)s.diplomacy=structuredClone(baselineDiplomacy.get(s.i)||[]);applyEconomicDiplomacy(D,work.exportData());}
 const work=await createWorkbench({...options,onUpdate:()=>{syncDiplomacy();cache=null;onChange();if(panel&&!panel.hidden)render();}}),data=await fetch('./economy-source.json?v=32',{cache:'no-store'}).then(r=>r.json());
 syncDiplomacy();
 function current(){
  if(cache)return cache;const recorded=work.exportState();if(basis==='simulated'&&!recorded.last)basis='current';const period=basis==='simulated'&&recorded.last?(recorded.last.periodDays||work.exportData().cycleDays):30,edits={...work.exportData(),cycleDays:period},model=createEconomy(D,data,edits),ps=provinces(),markets=createMarkets(D,data,model,{provinces:ps,provinceAt,state:recorded.last?recorded:null,recordedPrices:basis==='simulated'?recorded.last?.marketPrices:null}),cityReports=new Map(D.cities.map(b=>[b.i,model.city(b)])),provReports=new Map(ps.map(p=>[p.i,model.province(p.i,provinceAt)]));const ruralNodes=economicNodes(D,data,model,ps,provinceAt);for(const p of ps){const r=provReports.get(p.i),rural=new Map();for(const n of ruralNodes.values())if(n.province?.i===p.i)for(const [g,q]of n.report.rural)rural.set(g,(rural.get(g)||0)+q);r.rural=rural;r.production=new Map(rural);for(const b of r.cities)for(const [g,q]of model.city(b).production)r.production.set(g,(r.production.get(g)||0)+q);}
  const state=basis==='simulated'&&recorded.last?recorded:simulateEconomy(D,data,edits,recorded.last?recorded:null,ps,provinceAt,{instant:true}),flows=routeFlows(state.last.trades),stateReports=new Map();
  for(const s of D.states){const towns=D.cities.filter(b=>b.state===s.i),pp=ps.filter(p=>p.state===s.i),production=new Map(),inputs=new Map();for(const b of towns)for(const [g,n]of cityReports.get(b.i).production)production.set(g,(production.get(g)||0)+n);for(const b of towns)for(const [g,n]of cityReports.get(b.i).inputs)inputs.set(g,(inputs.get(g)||0)+n);for(const p of pp)for(const [g,n]of provReports.get(p.i).rural)production.set(g,(production.get(g)||0)+n);stateReports.set(s.i,{cities:towns,provinces:pp,production,inputs});}
  const tradeByState=new Map();for(const t of state.last.trades)for(const id of new Set([owner(t.from),owner(t.to)]))tradeByState.set(id,(tradeByState.get(id)||0)+t.coins/100);
  cache={provinceAt,edits,model,markets,cityReports,provReports,state,flows,stateReports,tradeByState,period};return cache;
 }
 const st=id=>D.states.find(s=>s.i===id),sn=id=>st(id)?.name?.trim()||'Terras livres',pn=id=>provinces().find(p=>p.i===id)?.name||'Zona rural',an=id=>id.startsWith('carrier:')?'Transportadores · '+sn(+id.split(':')[1]):id.startsWith('service:')?'Serviços · '+title(D.cities.find(b=>b.i===+id.split(':')[1])||{name:'Localidade'}):id.startsWith('state:')?'Alfândega · '+sn(+id.split(':')[1]):id.startsWith('city:')?title(D.cities.find(b=>b.i===+id.split(':')[1])||{name:'Cidade'}):pn(+id.split(':')[1]);
 function owner(account){const [kind,id]=account.split(':');return ['state','carrier'].includes(kind)?+id:['city','service'].includes(kind)?D.cities.find(b=>b.i===+id)?.state:provinces().find(p=>p.i===+id)?.state;}
 const value=(rows,model)=>[...rows].reduce((sum,[g,n])=>sum+n*model.price(g),0);
 function metrics(rows){return '<div class="ledgerMetrics">'+rows.map(([v,label])=>`<div><b>${v}</b><span>${label}</span></div>`).join('')+'</div>';}
 function nav(kind,id,name,detail='',icon='◈'){return `<button class="ledgerCard" data-ledger-kind="${kind}" data-ledger-id="${id}"><i>${icon}</i><span><b>${esc(name)}</b><small>${detail}</small></span><em>›</em></button>`;}
 function productRows(rows,c){return [...rows].sort((a,b)=>b[1]*c.model.price(b[0])-a[1]*c.model.price(a[0])).map(([id,n])=>{const g=c.model.goods.get(+id);return nav('good',id,g?.name,`${num(n)} ${esc(g?.unit)} · ${money(n*c.model.price(+id))}`,goodIcon(g));}).join('')||'<p class="muted">Sem produção nesta área.</p>';}
 function accountSet(){if(view.kind==='world')return new Set(Object.keys(current().state.accounts));if(view.kind==='city')return new Set(['city:'+view.id]);if(view.kind==='province')return new Set([...Object.keys(current().state.accounts).filter(k=>k==='province:'+view.id||k.startsWith('rural:'+view.id+':')),...current().provReports.get(view.id).cities.map(b=>'city:'+b.i)]);return new Set(Object.keys(current().state.accounts).filter(id=>owner(id)===view.id));}
 function external(c,ids){let imports=0,exports=0;for(const t of c.state.last.trades){if(ids.has(t.to)&&!ids.has(t.from))imports+=t.coins;if(ids.has(t.from)&&!ids.has(t.to))exports+=t.coins;}return {imports:imports/100,exports:exports/100};}
 function sorted(items,val,name){return items.filter(x=>name(x).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>order==='name'?name(a).localeCompare(name(b),'pt-BR'):val(b)-val(a));}
 function mapTools(){return `<div class="ledgerMapTools"><label>Visualizar no mapa<select id="ledgerMapMode"><option value="natural">Terreno</option>${ECONOMIC_MODES.map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></label><label>Produto<select id="ledgerMapGood">${data.goods.filter(g=>!g.inactive).map(g=>`<option value="${g.i}" ${g.i===good?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label><label><input type="checkbox" id="ledgerTraffic" checked> Caravanas e barcos em movimento</label></div>`;}
 function worldHTML(c){const total=[...c.stateReports.values()].reduce((v,r)=>v+value(r.production,c.model),0);return `<p class="ledgerIntro">Estimativa de 30 dias, sem avançar o tempo. Abra um estado para explorar suas províncias e cidades.</p>${metrics([[money(total),'Capacidade produtiva · referência'],[money(c.state.history.at(-1).tradeValue),'Comércio estimado / 30 dias'],[c.markets.regions.length,'Mercados regionais']])}<details><summary>População e abastecimento</summary><p>${num(c.state.last.population?.residents)} moradores permanentes · ${num(c.state.last.population?.itinerants)} itinerantes · entorno rural incluído nos totais das localidades. Visitantes deste período: ${num(c.state.last.population?.visitors)}.</p><p>Cada localidade representa a cidade e suas redondezas. Não há um segundo censo rural. Alimentos comerciais são atendidos antes das oficinas. Só 1% da oferta e da necessidade básica de alimentos entram neste balanço; 99% ficam abstraídos no abastecimento básico de fundo, sem criar produção adicional nas localidades. O panorama é uma taxa mensal acessível; os ciclos salvos registram chegadas e cargas em trânsito.</p></details><h3>Estados</h3>${sorted(D.states.filter(s=>s.i),s=>value(c.stateReports.get(s.i).production,c.model),s=>s.name).map(s=>{const r=c.stateReports.get(s.i);return nav('state',s.i,sn(s.i),`${r.cities.length} localidades · ${r.provinces.length} províncias · ${money(value(r.production,c.model))}`,s.coa?'⚑':'♜');}).join('')}`;}
 function territoryHTML(c){const kind=view.kind,id=view.id,r=kind==='state'?c.stateReports.get(id):kind==='province'?c.provReports.get(id):c.cityReports.get(id);if(!r){view={kind:'world'};return worldHTML(c);}const b=kind==='city'?D.cities.find(b=>b.i===id):null,p=kind==='province'?provinces().find(p=>p.i===id):null,name=b?title(b):p?p.name:sn(id),ids=accountSet(),ext=external(c,ids),production=new Map();for(const key of ids)for(const [g,n]of Object.entries(c.state.last.production[key]||{}))production.set(+g,(production.get(+g)||0)+n);
  return `<button data-ledger-kind="${kind==='city'&&provinceAt(b.cell)?'province':kind==='world'?'world':kind==='state'?'world':'state'}" data-ledger-id="${kind==='city'&&provinceAt(b.cell)?provinceAt(b.cell).i:p?.state||b?.state||0}">← ${kind==='state'?'Mundo':kind==='province'?'Estado':'Região'}</button><p class="eyebrow">${kind==='state'?'ESTADO':kind==='province'?'PROVÍNCIA':'LOCALIDADE'}${kind==='state'?'':' · '+esc(sn(p?.state||b?.state))}</p><h2>${esc(name)}</h2>${metrics([[money(value(r.production,c.model)),'Capacidade / 30 dias'],[money(ext.exports),'Vendas para fora · estimativa'],[money(ext.imports),'Compras de fora · estimativa']])}${b?`<p>Mercado: <button data-ledger-kind="market" data-ledger-id="${c.markets.cityMarket(b)?.i||0}">${esc(c.markets.cityMarket(b)?.name||'Sem mercado ativo')}</button> · ${esc(populationDescription(b))}</p><button id="ledgerLocate">Localizar no mapa ↗</button><button id="ledgerCapacity">Editar produção</button>`:''}${laborHTML(c,r.cities)}${incomeHTML(r.cities)}${consumptionHTML(c,r.cities)}${kind==='state'?'<h3>Províncias</h3>'+sorted(r.provinces,p=>value(c.provReports.get(p.i).production,c.model),p=>p.name).map(p=>nav('province',p.i,p.name,`${c.provReports.get(p.i).cities.length} localidades · ${money(value(c.provReports.get(p.i).production,c.model))}`,'▱')).join(''):''}${!b?'<h3>Cidades e localidades</h3>'+sorted(r.cities,b=>value(c.cityReports.get(b.i).production,c.model),title).map(b=>nav('city',b.i,title(b),`${esc(populationDescription(b))} · ${money(value(c.cityReports.get(b.i).production,c.model))}`,b.port?'⚓':b.citadel?'♜':'⌂')).join(''):''}<h3>Produção estimada</h3><p class="muted">Volume realizável após compras de insumos. A capacidade completa fica disponível para comparação abaixo.</p>${productRows(production,c)}${serviceHTML(c,ids)}<details><summary>Capacidade e insumos</summary><h4>Capacidade produtiva</h4>${productRows(r.production,c)}<h4>Insumos necessários</h4>${productRows(r.inputs,c)}</details>`;
 }
 function laborHTML(c,cities){const initial=cities.reduce((n,b)=>n+forcedLaborPeople(b),0);if(!initial)return '';const ids=new Set(cities.map(b=>'city:'+b.i)),installed=cities.reduce((n,b)=>n+(c.state.accounts['city:'+b.i]?.assets[31]||0),0),stock=cities.reduce((n,b)=>n+(c.state.accounts['city:'+b.i]?.stock[31]||0),0),trades=c.state.last.trades.filter(t=>t.good===31&&(ids.has(t.from)||ids.has(t.to)));return `<details class="ledgerLabor"><summary>⛓ Trabalho escravizado e comércio</summary><p>Regime de trabalho e estoque de pessoas existentes, incluídas no censo inicial. Não há salário atribuído às pessoas escravizadas; sua alimentação participa da demanda local. A apropriação de trabalho afeta os custos operacionais de referência, sem bônus automático de produção.</p>${metrics([[num(initial),'Pessoas no censo inicial · estimativa'],[num(installed),'Trabalho alocado na simulação'],[num(stock),'Estoque disponível para transferência']])}<p>${num(trades.reduce((n,t)=>n+t.units,0))} pessoas transferidas neste recorte. O percentual inicial é editável na cidade. Alterá-lo afeta uma nova simulação; ciclos já salvos conservam seus estoques.</p><button data-ledger-kind="good" data-ledger-id="31">Ver estoques e comércio de pessoas escravizadas</button></details>`;}
 function captiveHTML(c,g){const cities=D.cities.filter(b=>forcedLaborPeople(b)>0),trades=c.state.last.trades.filter(t=>t.good===31),held=cities.reduce((n,b)=>n+(c.state.accounts['city:'+b.i]?.assets[31]||0),0),available=cities.reduce((n,b)=>n+(c.state.accounts['city:'+b.i]?.stock[31]||0),0);return `<button data-ledger-kind="goods" data-ledger-id="0">← Todos os produtos</button><h2>⛓ Pessoas escravizadas</h2><p>Comércio de estoques finitos em Drácon, Husaj e Território Orc. Pessoas não são produzidas por ciclo nem consumidas como equipamento. Transferências respeitam rotas, guerras, embargos, fretes e tarifas.</p>${metrics([[num(held),'Trabalho alocado'],[num(available),'Estoque para transferência'],[num(trades.reduce((n,t)=>n+t.units,0)),'Pessoas transferidas no recorte']])}<p>Censo inicial estimado: 12% em Drácon, 15% em Husaj e 8% no Território Orc, fora das escolas de magia; são hipóteses editáveis. Não há captura ou reprodução automática. O censo urbano aprovado não é atualizado automaticamente por essas transferências.</p><h3>Localidades e estoques</h3>${cities.map(b=>nav('city',b.i,title(b),`${sn(b.state)} · ${num(c.state.accounts['city:'+b.i]?.assets[31]||0)} alocadas · ${num(c.state.accounts['city:'+b.i]?.stock[31]||0)} disponíveis`,'⛓')).join('')}<p>Capturas por piratas registradas: ${num(c.state.accounts['captivity:0']?.assets[31]||0)}. Essas pessoas continuam contabilizadas.</p><h3>Preços e ofertas</h3>${marketPrices(c,g)}<h3>Transações no recorte</h3>${trades.map(t=>`<p>${esc(an(t.from))} → ${esc(an(t.to))}: ${num(t.units)} pessoas · ${money(t.coins/100)}</p>`).join('')||'<p>Sem transferências neste recorte.</p>'}`;}
 function consumptionHTML(c,cities){const reports=cities.map(b=>c.state.last.householdConsumption?.['city:'+b.i]).filter(Boolean);if(!reports.length)return '';const rows=['peasant','modest','comfortable','wealthy','aristocratic'].map(id=>reports.flatMap(r=>r.classes).filter(r=>r.id===id)).filter(r=>r.length);return `<details class="ledgerConsumption"><summary>Consumo por classe social</summary><p>Camponeses priorizam subsistência e não recebem orçamento de luxo. As compras de luxo usam parte da renda disponível de cada estrato, limitada pelo caixa real, estoques e acesso. Moradia, tributos e a maior parte da subsistência ficam abstraídos.</p><table class="ledgerTable"><thead><tr><th>Estrato</th><th>Orçamento de luxo</th><th>Gasto / reservado</th></tr></thead><tbody>${rows.map(list=>`<tr><td>${esc(list[0].name)}</td><td>${money(list.reduce((n,r)=>n+r.luxuryBudget,0))}</td><td>${money(list.reduce((n,r)=>n+r.luxurySpent,0))}</td></tr>`).join('')}</tbody></table><p>Inclui o valor de estoques próprios consumidos e pagamentos de cargas ainda em trânsito. Não há criação de moedas para financiar o orçamento.</p></details>`;}
 function incomeHTML(cities){const a=aggregateIncome(cities);return `<details class="ledgerIncome"><summary>Composição social e poder de compra · estimativa</summary><p>A população inclui a cidade e o entorno rural. Renda por unidade familiar; não se atribui salário a cada dependente. Percentuais e tamanho familiar são editáveis na ficha da cidade.</p>${metrics([[money(a.gross),'Renda total de referência / mês'],[money(a.cash),'Parcela em moeda estimada'],[money(a.disposable),'Sobra após despesas básicas']])}<p class="muted">Inclui ${money(a.nonCash)} de valor estimado em espécie, autoconsumo e trocas. Esses valores não são receita do estado nem crédito automático ao caixa.</p>${cities.length===1?`<table class="ledgerTable"><thead><tr><th>Estrato</th><th>População</th><th>Parcela</th><th>Renda em moeda</th></tr></thead><tbody>${incomeReport(cities[0]).rows.map(r=>`<tr><td>${r.name}</td><td>${num(r.residents)}</td><td>${num(r.share)}%</td><td>${money(r.cash)}</td></tr>`).join('')}</tbody></table>`:''}</details>`;}
 function serviceHTML(c,ids){const rows=(c.state.last.services||[]).filter(r=>ids.has(r.payer)||ids.has(r.receiver));return rows.length?'<details><summary>Serviços e transporte · '+money(rows.reduce((s,r)=>s+r.coins,0)/100)+'</summary><p>Pagamentos entre contas; não entram no valor bruto dos bens.</p>'+rows.slice(0,50).map(r=>'<p>'+esc(an(r.payer||''))+' → '+esc(an(r.receiver))+' · '+money(r.coins/100)+'</p>').join('')+'</details>':'';}
 function goodsHTML(c){if(view.kind!=='good')return `<h2>Produtos e insumos</h2><p class="muted">Escolha um bem para comparar produção, preços e comércio. Moedas cunhadas e elefantes sem atividade estão arquivados. Pessoas escravizadas são estoques transferidos, nunca produção mensal.</p>${sorted(data.goods.filter(g=>!g.inactive),g=>[...c.stateReports.values()].reduce((s,r)=>s+(r.production.get(g.i)||0),0)*c.model.price(g.i),g=>g.name).map(g=>nav('good',g.i,g.name,`${money(c.model.price(g.i))} / ${esc(g.unit)} · ${g.i===31?'Estoque finito · comércio':g.kind==='manufacture'?'Manufaturado':'Recurso / extração'}`,goodIcon(g))).join('')}`;
  const g=c.model.goods.get(view.id),ranks=Object.entries(c.state.last.production).map(([id,rows])=>({id,n:rows[g.i]||0})).filter(r=>r.n>0).sort((a,b)=>b.n-a.n);good=g.i;if(g.i===31)return captiveHTML(c,g);
  return `<button data-ledger-kind="goods" data-ledger-id="0">← Todos os produtos</button><h2>${goodIcon(g)} ${esc(g.name)}</h2>${metrics([[num(ranks.reduce((s,r)=>s+r.n,0))+' '+esc(g.unit),'Produção estimada / 30 dias'],[ranks.length,'Localidades produtoras']])}${g.i===31?'<p>Pessoas escravizadas: não há fabricação ou geração mensal. O estoque inicial é uma parcela estimada dos habitantes existentes de Drácon, Husaj e Território Orc. Comércio e bloqueios seguem as rotas; capturas por piratas ficam registradas separadamente. O censo aprovado permanece como referência inicial, sem atualização demográfica automática por transferência.</p>':''}<h3>Onde é produzido</h3>${ranks.map(r=>nav(r.id.startsWith('rural:')?'province':r.id.split(':')[0],+r.id.split(':')[1],an(r.id),`${num(r.n)} ${esc(g.unit)} · ${esc(sn(owner(r.id)))}`)).join('')||'<p>Sem produção realizável no cenário atual.</p>'}<h3>Preços por mercado</h3>${marketPrices(c,g)}<p class="muted">${g.massTonnes?num(g.massTonnes)+' t por unidade · ':''}${g.foodPeopleDays?num(g.foodPeopleDays)+' pessoas-dia de alimentação · ':''}${g.durable?'Bem durável: estoque instalado e desgaste anual, sem consumo integral mensal.':''}</p><h3>Insumos por unidade</h3>${g.recipes?.length?g.recipes.map(recipe=>Object.entries(recipe).map(([id,n])=>nav('good',id,c.model.goods.get(+id)?.name,`${num(n)} ${esc(c.model.goods.get(+id)?.unit)}`,goodIcon(c.model.goods.get(+id)))).join('')).join(''):`<p class="muted">${esc(g.process||'Extração ou produção primária, sem receita de fabricação registrada.')}</p>`}`;
 }
 function marketPrices(c,g){
  if(!c.quoteNodes){c.quoteNodes=economicNodes(D,data,c.model,provinces(),provinceAt);for(const n of c.quoteNodes.values())n.city??=n.cityReference;const graph=tradeGraph(D,c.quoteNodes,c.edits);c.quotePaths=graph.paths;c.waterQuotePaths=graph.waterPaths;}
  return '<table class="ledgerTable"><thead><tr><th>Mercado</th><th>Referência local</th><th>Menor oferta entregue</th></tr></thead><tbody>'+[...c.markets.regions].sort((a,b)=>c.markets.price(a.center,g.i)-c.markets.price(b.center,g.i)).map(m=>{const offers=[];for(const [id,rows]of Object.entries(g.i===31?Object.fromEntries(Object.entries(c.state.accounts).map(([id,a])=>[id,a.stock])):c.state.last.production)){if(!(rows[g.i]>0))continue;const seller=c.quoteNodes.get(id),path=(g.transport?c.waterQuotePaths:c.quotePaths).get('city:'+m.center.i)?.get(id);if(!seller?.city||!path||atWar(D,c.edits,m.center.state,seller.state))continue;const quote=tradeQuote(D,c.edits,{sellerState:seller.state,buyerState:m.center.state,good:g.i,price:c.markets.price(seller.city,g.i),cost:quotedUnitCost(c.model,c.markets,seller.city,g.i,c.state.accounts[id]),path});if(quote)offers.push({price:quote.delivered,id});}offers.sort((a,b)=>a.price-b.price);return `<tr><td><button data-ledger-kind="market" data-ledger-id="${m.i}">${esc(m.name)}</button></td><td>${money(c.markets.price(m.center,g.i))}</td><td>${offers[0]?money(offers[0].price)+'<small>'+esc(an(offers[0].id))+'</small>':'Sem oferta acessível'}</td></tr>`;}).join('')+'</tbody></table><p class="muted">Por '+esc(g.unit)+'. Referência local sem frete; oferta entregue inclui transporte, relação diplomática, tarifas e risco de perda até a sede do mercado; respeita embargos e bloqueios. Cotação indicativa por unidade comercial, sem reservar estoque ou caixa. Pesos e cobertura alimentar definidos na ficha do produto; valores de referência do cenário.</p>';
 }
 function maps(){const c=current();return c.maps??=buildEconomicMap(D,c,provinces(),provinceAt,{goodsBasis});}
 function comparisonCell(c,m,g){
  c.priceComparisons??=createMarketComparisons(D,c,maps(),provinces());const r=c.priceComparisons(m,g.i),delta=(label,n,tip)=>{const v=n===null?null:Math.abs(n)<.05?0:n,sign=v>0?'+':'';return `<span class="priceDelta ${v===null||v===0?'flat':v>0?'higher':'lower'}" title="${esc(tip)}">${label} ${v===null?'—':sign+v.toLocaleString('pt-BR',{maximumFractionDigits:1})+'%'}</span>`;};
  const title=`Preço local ${money(r.local)}; base ${money(r.base)}; média simples dos ${c.markets.regions.length} mercados ${r.globalMean===null?'sem referência':money(r.globalMean)}. Próximos: ${r.neighbours.map(n=>n.name).join(', ')}; média ${r.nearMean===null?'sem referência':money(r.nearMean)}. Preços por ${g.unit}.`;
  const freightTitle=r.supplierCount?`Média simples de ${r.offerCount} cotações unitárias entre ${r.supplierCount} fornecedores externos e as cidades acessíveis deste mercado. Cada par origem-destino tem o mesmo peso. Origem média ${money(r.originMean)}; frete médio ${money(r.freightMean)}; tarifa média ${money(r.tariffMean||0)}; risco médio ${num((r.riskMean||0)*100)}%. Entrega média ${money(r.deliveredMean)} por ${g.unit}. Inclui relações, tarifas, pirataria, embargos e bloqueios atuais, sem reservar estoque ou caixa. Não se soma o preço local novamente.`:'Nenhuma cidade deste mercado tem fornecedor externo com produção e caminho acessível no recorte. Ausência de oferta não significa frete zero.';
  return `<td class="priceComparison" aria-label="Comparação de ${esc(g.name)}"><div class="priceDeltas" title="${esc(title)}">${delta('Base',r.vsBase,'Em relação ao preço-base do bem: '+money(r.base))}${delta('Média',r.vsGlobal,'Média simples de todos os mercados: '+(r.globalMean===null?'—':money(r.globalMean)))}${delta('Próximos',r.vsNear,'Média dos três outros centros mais próximos: '+r.neighbours.map(n=>n.name).join(', ')+(r.nearMean===null?'':'; '+money(r.nearMean)))}</div><small class="priceFreight" title="${esc(freightTitle)}">${r.supplierCount?'Frete médio +'+money(r.freightMean)+'<br><b>Importar ≈ '+money(r.deliveredMean)+'</b>':'Frete: sem oferta externa'}</small></td>`;
 }
 function marketsHTML(c){const thematic=maps();
  if(view.kind!=='market')return `<h2>Mercados regionais</h2><p class="muted">Centros comerciais com áreas próprias, independentes das fronteiras políticas. Clique no nome ou na região do modo Mercados para abrir a ficha.</p><button id="showMarketsMap">◉ Ver mercados no mapa</button>${[...thematic.marketInfo.values()].sort((a,b)=>b.localValue-a.localValue).map(m=>nav('market',m.i,m.name,`${m.registeredCities.length} localidades · ${m.states.size} estados · produção ${money(m.localValue)}`,'⚖')).join('')}`;
  const m=thematic.marketInfo.get(view.id);if(!m){view={kind:'markets'};return marketsHTML(c);}
  const ranked=[...m.production].sort((a,b)=>b[1]*c.markets.price(m.center,b[0])-a[1]*c.markets.price(m.center,a[0])),links=[...thematic.links.values()].filter(l=>l.from===m.i||l.to===m.i).sort((a,b)=>b.coins-a.coins),priceRows=data.goods.filter(g=>g.name.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));
  return `<button data-ledger-kind="markets" data-ledger-id="0">← Mercados</button><h2><span class="marketSwatch" style="background:${m.color}"></span>${esc(m.name)}</h2><p class="muted">Sede em ${esc(m.center.name)} · ${esc(sn(m.center.state))} · ${m.registeredCities.length} localidades (${m.cities.length} ativas) de ${m.states.size} estados. ${basis==='simulated'?'Resultado do ciclo registrado.':'Panorama estimado de 30 dias.'}</p>${metrics([[money(m.localValue),'Produção · preços locais'],[money(m.incoming),'Compras de outros mercados'],[money(m.outgoing),'Vendas a outros mercados']])}<button id="locateMarket" data-market-id="${m.i}">Localizar este mercado ↗</button><h3>Principais bens produzidos</h3><table class="ledgerTable"><thead><tr><th>Bem</th><th>Volume</th><th>Preço local / un.</th><th>Valor local</th><th>Comparação + frete</th></tr></thead><tbody>${ranked.slice(0,10).map(([id,n])=>{const g=c.model.goods.get(id);return `<tr><td><button data-ledger-kind="good" data-ledger-id="${id}">${goodSymbol(g)} ${esc(g.name)}</button></td><td>${num(n)} ${esc(g.unit)}</td><td>${money(c.markets.price(m.center,id))}</td><td>${money(n*c.markets.price(m.center,id))}</td>${comparisonCell(c,m,g)}</tr>`;}).join('')||'<tr><td colspan="5">Sem produção neste recorte.</td></tr>'}</tbody></table><p class="muted">Comparação: preço local versus base, média de todos os mercados e média dos três centros mais próximos. Entrega já inclui diplomacia, tarifas e risco de perda; passe o cursor para os detalhes.</p><p class="muted">A produção e o valor reúnem os participantes urbanos e rurais uma única vez. Valor de produção não é lucro ou valor arrecadado.</p><h3>Províncias participantes</h3>${[...m.provinceParticipants.values()].sort((a,b)=>a.province.name.localeCompare(b.province.name,'pt-BR')).map(row=>{const total=D.cities.filter(b=>!b.excluded&&provinceAt(b.cell)?.i===row.province.i).length;return nav('province',row.province.i,row.province.name,`${row.cities.length} de ${total} localidades · ${sn(row.province.state)}`,'▱');}).join('')}<h3>Estados participantes</h3>${[...m.states.values()].sort((a,b)=>b.value-a.value).map(r=>nav('state',r.id,sn(r.id),`${r.cities} cidades · ${money(r.value)} em produção a preços-base`,'⚑')).join('')}<h3>Fluxos entre mercados</h3>${links.map(l=>{const incoming=l.to===m.i,other=thematic.marketInfo.get(incoming?l.from:l.to);return nav('market',other.i,(incoming?'← Compra de ':'→ Venda a ')+other.center.name,`${money(l.coins/100)} · ${l.trades} transferências · ${[...l.goods].sort((a,b)=>b[1]*c.model.price(b[0])-a[1]*c.model.price(a[0])).slice(0,3).map(([g])=>esc(c.model.goods.get(g)?.name)).join(', ')}`,incoming?'↙':'↗');}).join('')||'<p class="muted">Sem fluxo externo neste recorte.</p>'}<details><summary>Preços de todos os bens e estoques dos participantes</summary><p class="muted">Preços sem frete. Estoques agregados das cidades e áreas rurais; não representam um depósito comum ou acesso garantido. Use o filtro acima para buscar um bem.</p><table class="ledgerTable"><thead><tr><th>Bem</th><th>Preço / unidade</th><th>Estoque agregado</th><th>Comparação + frete</th></tr></thead><tbody>${priceRows.map(g=>`<tr><td><button data-ledger-kind="good" data-ledger-id="${g.i}">${goodSymbol(g)} ${esc(g.name)}</button></td><td>${money(c.markets.price(m.center,g.i))} / ${esc(g.unit)}</td><td>${num(m.stock.get(g.i)||0)} ${esc(g.unit)}</td>${comparisonCell(c,m,g)}</tr>`).join('')}</tbody></table></details><details><summary>Localidades atendidas · ${m.registeredCities.length}</summary>${sorted(m.registeredCities,b=>value(c.cityReports.get(b.i).production,c.model),title).map(b=>nav('city',b.i,title(b),sn(b.state),b.port?'⚓':'⌂')).join('')}</details>`;
 }
 function flowHTML(id){const c=current(),f=c.flows.get(id);return `<section class="ledgerRouteFlow"><h3>Fluxo de bens · ${basis==='simulated'?'ciclo '+c.state.cycle:'panorama atual'}</h3>${f?`${metrics([[money(f.coins/100),'Valor transportado / '+c.period+' dias'],[f.trades,'Transferências estimadas']])}<p class="muted">Valor dos bens que usam este trecho; não é receita da estrada. Uma carga pode passar por várias rotas e não deve ser somada novamente no total mundial.</p><details><summary>Produtos transportados · ${Object.keys(f.goods).length} bens</summary><div>${Object.entries(f.goods).sort((a,b)=>b[1]-a[1]).map(([g,n])=>'<p>'+goodIcon(c.model.goods.get(+g))+' '+esc(c.model.goods.get(+g)?.name)+' · '+num(n)+' '+esc(c.model.goods.get(+g)?.unit)+'</p>').join('')}</div></details>`:'<p class="muted">Sem fluxo estimado neste traçado no cenário atual.</p>'}</section>`;}
 function routesHTML(c){return `<h2>Fluxos comerciais</h2><p class="muted">Estimativa mensal sobre as rotas existentes. Clique para abrir o traçado e sua lista de bens.</p>${sorted(D.routes.filter(r=>r.enabled!==false),r=>c.flows.get(r.id)?.coins||0,r=>r.name).map(r=>nav('route',r.id,r.name,`${money((c.flows.get(r.id)?.coins||0)/100)} em bens / 30 dias`,r.kind==='sea'?'⛵':r.kind==='mixed'?'↝⚓':'♞')).join('')}`;}
 function diplomacyHTML(c){const states=D.states.filter(s=>s.i&&s.i!==17);return `<h2>Diplomacia e comércio</h2><p>Declarar guerra bloqueia o comércio direto entre as duas nações e o trânsito terrestre do comprador por território inimigo. O sistema busca fornecedores acessíveis pelo menor preço entregue, incluindo fretes.</p><form id="ledgerDiplomacy"><label>Estado<select id="econStateA">${states.map(s=>`<option value="${s.i}">${esc(sn(s.i))}</option>`).join('')}</select></label><label>Outro estado<select id="econStateB">${[...states].reverse().map(s=>`<option value="${s.i}">${esc(sn(s.i))}</option>`).join('')}</select></label><label>Nova relação<select id="econRelation"><option value="Neutral">Neutra / paz</option><option value="Friendly">Amistosa</option><option value="Ally">Aliada</option><option value="Suspicion">Desconfiança</option><option value="Rival">Rivalidade</option><option value="Enemy">Inimizade</option><option value="War">Em guerra</option></select></label><button type="submit">Aplicar relação e recalcular panorama</button><p id="econRelationNow" class="muted"></p></form><button id="resetEconDiplomacy">Restaurar relações do padrão</button><p class="muted">A mudança não desfaz ciclos já registrados; afeta o panorama e os próximos ciclos. A mesma relação aparece nas fichas dos estados.</p>${tradePolicyHTML(D,data,c.edits)}<h3>Guerras que afetam o comércio</h3>${states.flatMap((s,i)=>states.slice(i+1).filter(t=>atWar(D,c.edits,s.i,t.i)).map(t=>`<p>⚔ ${esc(sn(s.i))} × ${esc(sn(t.i))}</p>`)).join('')||'<p>Nenhuma guerra ativa.</p>'}`;}
 function render(){if(!panel)return;const c=current();panel.innerHTML=`<div class="ledgerHeader"><div><small>ECONOMIA · PANORAMA ATUAL</small><h1>Livro de comércio</h1></div><button id="closeLedger" aria-label="Fechar livro de comércio">✕</button></div><nav class="ledgerTabs">${[['world','Estados'],['goods','Produtos'],['markets','Mercados'],['routes','Rotas'],['diplomacy','Diplomacia']].map(([key,name])=>`<button data-ledger-tab="${key}" class="${section===key?'active':''}">${name}</button>`).join('')}</nav><div class="ledgerSource"><label>Recorte<select id="ledgerBasis"><option value="current" ${basis==='current'?'selected':''}>Panorama atual · estimativa mensal</option><option value="simulated" ${basis==='simulated'?'selected':''} ${work.exportState().last?'':'disabled'}>Último ciclo simulado · ${work.exportState().cycle}</option></select></label></div><div class="ledgerToolbar"><input id="ledgerSearch" placeholder="Filtrar lista…" aria-label="Filtrar economia" value="${esc(query)}"><select id="ledgerOrder" aria-label="Ordenar economia"><option value="value" ${order==='value'?'selected':''}>Maior valor</option><option value="name" ${order==='name'?'selected':''}>Nome A–Z</option></select></div><div class="ledgerContent">${section==='world'?view.kind==='world'?worldHTML(c):territoryHTML(c):section==='goods'?goodsHTML(c):section==='markets'?marketsHTML(c):section==='routes'?routesHTML(c):diplomacyHTML(c)}</div><details class="ledgerMapOptions"><summary>◉ Modos econômicos do mapa</summary>${mapTools()}</details><div class="ledgerFooter"><button id="ledgerSimulation">⏱ Simular ciclos futuros</button><button id="ledgerSettings">⚙ Preços e ajustes</button><small>1 PO = 10 PP = 100 PC · valores estimados, sem avançar o calendário</small></div>`;
  panel.innerHTML=panel.innerHTML.replaceAll('30 dias',c.period+' dias');if(basis==='simulated')panel.innerHTML=panel.innerHTML.replaceAll('panorama atual','último ciclo').replaceAll('PANORAMA ATUAL','ÚLTIMO CICLO').replace('Panorama estimado para','Resultado registrado do ciclo '+c.state.cycle+' para').replace('com as cidades, províncias, mercados e relações atuais. Consultar esta visão não avança o tempo.','As compras e volumes são do ciclo registrado; preços de referência e capacidades seguem os ajustes vigentes.');const $=s=>panel.querySelector(s);bindTradePolicies(panel,{getEdits:()=>work.exportData(),onSave:raw=>work.importData(raw),toast});$('#ledgerBasis').onchange=e=>{basis=e.target.value;cache=null;onChange();render();};$('#closeLedger').onclick=close;for(const el of panel.querySelectorAll('[data-ledger-tab]'))el.onclick=()=>{section=el.dataset.ledgerTab;view={kind:section};query='';render();};for(const el of panel.querySelectorAll('[data-ledger-kind]'))el.onclick=()=>navigate(el.dataset.ledgerKind,el.dataset.ledgerId);
  $('#ledgerSearch').onchange=e=>{query=e.target.value;render();};$('#ledgerOrder').onchange=e=>{order=e.target.value;render();};$('#ledgerSimulation').onclick=()=>work.open({tab:'simulation'});$('#ledgerSettings').onclick=()=>work.open({tab:'settings'});
  const updateMap=()=>{good=+$('#ledgerMapGood').value;onMap($('#ledgerMapMode').value,good);};$('#ledgerMapMode').onchange=updateMap;$('#ledgerMapGood').onchange=updateMap;$('#ledgerTraffic').onchange=e=>onChange({traffic:e.target.checked});
  if(busy)$('#ledgerDiplomacy')?.setAttribute('aria-busy','true');if($('#resetEconDiplomacy'))$('#resetEconDiplomacy').onclick=()=>{work.importData({...work.exportData(),diplomacy:{}});toast('Relações do padrão restauradas.');};if($('#ledgerDiplomacy')){$('#econStateA').value=String(diploA);$('#econStateB').value=String(diploB);$('#econRelation').value=diploRelation;const relationNow=()=>{const a=+$('#econStateA').value,b=+$('#econStateB').value;diploA=a;diploB=b;diploRelation=tradeRelation(D,c.edits,a,b);$('#econRelation').value=diploRelation;$('#econRelationNow').textContent=a===b?'Selecione dois estados diferentes.':atWar(D,c.edits,a,b)?'Relação atual: em guerra.':'Relação atual: comércio permitido.';};$('#econStateA').onchange=$('#econStateB').onchange=relationNow;relationNow();$('#ledgerDiplomacy').onsubmit=e=>{e.preventDefault();const a=+$('#econStateA').value,b=+$('#econStateB').value;if(a===b)return toast('Escolha dois estados diferentes.');diploRelation=$('#econRelation').value;const next={...work.exportData(),diplomacy:{...work.exportData().diplomacy,[pairKey(a,b)]:$('#econRelation').value}};work.importData(next);cache=null;render();toast('Relação atualizada; panorama recalculado.');};}
  if($('#showMarketsMap'))$('#showMarketsMap').onclick=()=>onMap('economicMarkets',good);if($('#locateMarket'))$('#locateMarket').onclick=()=>{const m=maps().marketInfo.get(+$('#locateMarket').dataset.marketId);onMap('economicMarkets',good);focus(m.center.x,m.center.y,550);};if($('#ledgerLocate'))$('#ledgerLocate').onclick=()=>{const b=D.cities.find(b=>b.i===view.id);focus(b.x,b.y,180);};if($('#ledgerCapacity'))$('#ledgerCapacity').onclick=()=>work.open({cityId:view.id});
 }
 function navigate(kind,id){if(kind==='route'){close();onRoute(id);return;}view={kind,id:+id};section=['good','goods'].includes(kind)?'goods':['market','markets'].includes(kind)?'markets':'world';render();panel.querySelector('.ledgerContent').scrollTop=0;}
 function close(){if(panel)panel.hidden=true;}
 function open(target={}){beforeOpen();work.close();cache=null;if(!panel){panel=document.createElement('aside');panel.id='economyLedger';panel.setAttribute('aria-label','Livro de comércio e economia');document.body.append(panel);}panel.hidden=false;if(target.diplomacyStateId){diploA=target.diplomacyStateId;diploB=target.diplomacyTargetId||D.states.find(s=>s.i&&s.i!==17&&s.i!==diploA)?.i;diploRelation=tradeRelation(D,work.exportData(),diploA,diploB);}section=target.diplomacyStateId?'diplomacy':target.marketId?'markets':target.goodId?'goods':'world';view=target.marketId?{kind:'market',id:target.marketId}:target.goodId?{kind:'good',id:target.goodId}:target.cityId?{kind:'city',id:target.cityId}:target.provinceId?{kind:'province',id:target.provinceId}:target.stateId?{kind:'state',id:target.stateId}:{kind:'world'};render();}
 function mapValue(mode,cellId,selectedGood){const c=current(),cell=D.cells[cellId],p=provinceAt(cellId),r=p?c.provReports.get(p.i):c.stateReports.get(cell.state);if(!r||cell.state===17)return 0;if(mode==='economicProduction')return r.production.get(selectedGood)||0;if(mode==='economicPrice'){const hub=[...r.cities].sort((a,b)=>(b.demographics?.population||0)-(a.demographics?.population||0))[0],m=(hub?c.markets.cityMarket(hub):null)||[...c.markets.regions].sort((a,b)=>Math.hypot(cell.p[0]-a.center.x,cell.p[1]-a.center.y)-Math.hypot(cell.p[0]-b.center.x,cell.p[1]-b.center.y))[0];return m?c.markets.price(m.center,selectedGood):0;}return c.tradeByState.get(cell.state)||0;}
 return {...work,open,close,routeHTML:flowHTML,current,mapValue,maps,goodsBasis:()=>goodsBasis,setGoodsBasis(value){if(!['specialization','total'].includes(value))return;goodsBasis=value;const c=current();c.maps=null;},goodsList:()=>data.goods.filter(g=>!g.inactive),setGood(g){if(data.goods.some(v=>v.i===g)){good=g;if(panel?.querySelector('#ledgerMapGood'))panel.querySelector('#ledgerMapGood').value=String(g);}},setMapMode(m){if(panel?.querySelector('#ledgerMapMode'))panel.querySelector('#ledgerMapMode').value=m.startsWith('economic')?m:'natural';},invalidate(){cache=null;},importData(raw){work.importData(raw);applyEconomicDiplomacy(D,work.exportData());cache=null;},importState(raw){work.importState(raw);cache=null;}};
}
